mapper.select:
SELECT
    COUNT(1)
FROM
    user_dept ud
    INNER JOIN sys_user u ON u.id = ud.user_id
WHERE
    ud.dept_id = #{deptId}
    AND ud.status IN (1, 2)

    AND (
        u.username LIKE CONCAT('%', #{query.keyword}, '%')
        OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND u.status = #{query.status}


    AND ud.status = #{query.relationStatus}


    AND ud.is_primary = #{query.isPrimary}

SELECT u.id, u.username, u.status, u.nickname, u.avatar, u.gender, u.employee_no, ud.is_primary, ud.status AS relation_status FROM user_dept ud INNER JOIN sys_user u ON u.id = ud.user_id WHERE ud.dept_id = #{deptId} AND ud.status IN (1, 2)
AND ( u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') )
AND u.status = #{query.status}
AND ud.status = #{query.relationStatus}
AND ud.is_primary = #{query.isPrimary}
ORDER BY ud.is_primary DESC, ud.created_at DESC, u.username

SELECT COUNT(1) FROM sys_post p WHERE p.dept_id = #{deptId}
AND p.post_code LIKE CONCAT('%', #{query.postCode}, '%')
AND p.post_name LIKE CONCAT('%', #{query.postName}, '%')
AND p.status = #{query.status}

SELECT p.id, p.post_code, p.post_name, p.status FROM sys_post p WHERE p.dept_id = #{deptId}
AND p.post_code LIKE CONCAT('%', #{query.postCode}, '%')
AND p.post_name LIKE CONCAT('%', #{query.postName}, '%')
AND p.status = #{query.status}
ORDER BY p.order_num, p.post_code
